def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    # Parse and validate current version
    parts = current.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid version: {current}")

    try:
        major, minor, patch = [int(p) for p in parts]
    except ValueError:
        raise ValueError(f"Invalid version: {current}")

    # Check for leading zeros
    for i, p in enumerate(parts):
        if p != str(int(p)):
            raise ValueError(f"Invalid version: {current}")

    # Analyze commits to find strongest change type
    change_type = None  # None, 'fix', 'feature', or 'breaking'

    for commit in commits:
        lines = commit.split('\n')
        header = lines[0]

        # Parse header: type: text or type(scope): text
        if ':' not in header:
            continue

        colon_idx = header.index(':')
        before_colon = header[:colon_idx]

        # Check for breaking ! before colon
        is_breaking = before_colon.endswith('!')
        if is_breaking:
            before_colon = before_colon[:-1]

        # Parse type and scope
        type_part = None
        if '(' in before_colon:
            # type(scope) format
            type_end = before_colon.index('(')
            type_part = before_colon[:type_end]
            scope_start = type_end + 1
            scope_end = before_colon.rfind(')')
            if scope_end == -1 or scope_end <= scope_start:
                continue
            scope = before_colon[scope_start:scope_end]
            if not scope or '(' in scope or ')' in scope:
                continue
        else:
            # type format
            type_part = before_colon

        # Validate type (lowercase letters only)
        if not type_part or not type_part.islower() or not type_part.isalpha():
            continue

        # Check for exactly one space after colon
        if len(header) <= colon_idx + 1 or header[colon_idx + 1] != ' ':
            continue

        # Check for BREAKING CHANGE trailer in body
        for line in lines[1:]:
            if line.startswith('BREAKING CHANGE: ') or line.startswith('BREAKING-CHANGE: '):
                is_breaking = True
                break

        # Determine commit change type
        commit_change = None
        if is_breaking:
            commit_change = 'breaking'
        elif type_part == 'feat':
            commit_change = 'feature'
        elif type_part == 'fix':
            commit_change = 'fix'

        # Update strongest change (breaking > feature > fix)
        if commit_change:
            if change_type is None:
                change_type = commit_change
            elif commit_change == 'breaking':
                change_type = 'breaking'
            elif change_type != 'breaking' and commit_change == 'feature':
                change_type = 'feature'

    # Calculate next version
    if change_type is None:
        return current

    if major >= 1:
        # From 1.0.0 on
        if change_type == 'breaking':
            return f"{major + 1}.0.0"
        elif change_type == 'feature':
            return f"{major}.{minor + 1}.0"
        else:  # fix
            return f"{major}.{minor}.{patch + 1}"
    else:
        # Below 1.0.0 (major is 0)
        if change_type == 'breaking':
            return f"0.{minor + 1}.0"
        else:  # feature or fix
            return f"0.{minor}.{patch + 1}"
